declare(strict_types=1);require __DIR__.'/common.php';if(($_SERVER['REQUEST_METHOD']??'GET')!=='GET')respond(405,['error'=>'只支持 GET']);$limit=max(1,min(100,(int)($_GET['limit']??50)));$offset=max(0,(int)($_GET['offset']??0));$sort=(string)($_GET['sort']??'time_desc');if(!in_array($sort,['time_asc','time_desc','views_asc','views_desc'],true))$sort='time_desc';$ids=[];if(isset($_GET['ids']))foreach(array_slice(explode(',',(string)$_GET['ids']),0,20) as $v){$id=safe_id(trim($v));if($id)$ids[$id]=true;}$admin=admin_authenticated();$projects=[];foreach(glob(PROJECT_ROOT.'/*',GLOB_ONLYDIR)?:[] as $dir){$id=basename($dir);if(!safe_id($id)||(isset($_GET['ids'])&&!isset($ids[$id])))continue;$p=read_project_file($id);if(!$p)continue;$c=is_array($p['config']??null)?$p['config']:[];$owned=project_owned_by_requester($p);$projects[]=['id'=>$id,'title'=>(string)($c['title']??'我的知了'),'subtitle'=>(string)($c['subtitle']??''),'accent'=>(string)($c['accent']??'#e76543'),'publishedAt'=>(string)($p['updatedAt']??$p['publishedAt']??$c['createdAt']??''),'views'=>project_views($id),'hasImage'=>!empty($p['imageUrl']),'hasAudio'=>!empty($p['audioUrl']),'passwordProtected'=>!empty($p['access']['passwordHash']),'imageUrl'=>!empty($p['imageUrl'])?(string)$p['imageUrl']:null,'ownedByRequester'=>$owned,'canEdit'=>$owned||$admin,'canDelete'=>$admin,'url'=>base_url().'/?id='.$id];}usort($projects,static function($a,$b)use($sort){$r=str_starts_with($sort,'views_')?($a['views']<=>$b['views']):strcmp($a['publishedAt'],$b['publishedAt']);if(str_ends_with($sort,'_desc'))$r*=-1;return $r!==0?$r:strcmp($b['publishedAt'],$a['publishedAt']);});$total=count($projects);respond(200,['items'=>array_slice($projects,$offset,$limit),'total'=>$total,'limit'=>$limit,'offset'=>$offset,'sort'=>$sort,'adminAuthenticated'=>$admin]);
